		if err != nil {
			return nil, err
		}
		renameBriefLinkEndpoints(links, renames)

		rendered.Topology = &clabernetesRenderTopology{
			Defaults: config.Topology.Defaults,
			Kinds:    config.Topology.Kinds,
			Nodes:    config.Topology.Nodes,
			Groups:   config.Topology.Groups,
			Links:    links,
		}
	}

